import { sql, type Kysely } from 'kysely';

/**
 * VC-1-01: PropertyReference (data-model.md §9) and AuditRecord (§57).
 *
 * - The natural key `(mre_realm_id, mre_property_id)` is unique, so the same MRE
 *   Property can be linked only once per Realm (BR-ID-002) — also under
 *   concurrent requests.
 * - `mre_property_id` must be an MRE ObjectId (mre-integration.md §21.1).
 * - `id` is generated by PostgreSQL and never derived from MRE identity (§4.1).
 */
export async function up(db: Kysely<unknown>): Promise<void> {
  await sql`
    CREATE TABLE property_reference (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      mre_realm_id text NOT NULL CHECK (mre_realm_id <> ''),
      mre_property_id text NOT NULL CHECK (mre_property_id ~ '^[0-9a-f]{24}$'),
      external_reference_state text NOT NULL
        CHECK (external_reference_state IN ('ACTIVE', 'MISSING', 'DELETED_UPSTREAM', 'UNRESOLVED')),
      display_name text,
      cached_address jsonb CHECK (cached_address IS NULL OR jsonb_typeof(cached_address) = 'object'),
      last_refreshed_at timestamptz,
      created_at timestamptz NOT NULL DEFAULT now(),
      created_by text NOT NULL,
      updated_at timestamptz NOT NULL DEFAULT now(),
      version integer NOT NULL DEFAULT 1,
      CONSTRAINT property_reference_mre_identity_key UNIQUE (mre_realm_id, mre_property_id)
    )
  `.execute(db);

  await sql`
    CREATE TABLE audit_record (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      entity_type text NOT NULL,
      entity_id text NOT NULL,
      action text NOT NULL,
      occurred_at timestamptz NOT NULL DEFAULT now(),
      actor_type text NOT NULL CHECK (actor_type IN ('USER', 'SYSTEM')),
      actor_id text,
      metadata jsonb
    )
  `.execute(db);
  await sql`CREATE INDEX audit_record_entity_idx ON audit_record (entity_type, entity_id)`.execute(db);
}

export async function down(db: Kysely<unknown>): Promise<void> {
  await sql`DROP TABLE audit_record`.execute(db);
  await sql`DROP TABLE property_reference`.execute(db);
}
